import express from 'express';
import http from 'http';

const app = express();
const server = http.createServer(app);

// Track active connections for graceful drain
const connections = new Set<any>();
server.on('connection', (conn) => {
  connections.add(conn);
  conn.on('close', () => connections.delete(conn));
});

server.listen(3000, () => {
  console.log('Server running on :3000');
});

// SIGTERM: sent by PM2/Docker/Kubernetes when stopping the process
process.on('SIGTERM', gracefulShutdown);
process.on('SIGINT', gracefulShutdown);  // Ctrl+C in development

async function gracefulShutdown() {
  console.log('SIGTERM received, starting graceful shutdown');

  // 1. Stop accepting new connections
  server.close(() => {
    console.log('HTTP server closed');
  });

  // 2. Wait for active requests to finish (max 30 seconds)
  const shutdownTimeout = setTimeout(() => {
    console.error('Graceful shutdown timeout — forcing exit');
    process.exit(1);
  }, 30_000);

  // 3. Close database connections
  await db.end();
  console.log('Database connections closed');

  // 4. Close Redis connection
  await redis.quit();

  clearTimeout(shutdownTimeout);
  process.exit(0);
}

// Every app that wants zero-downtime deploys MUST have a /health endpoint
// The load balancer / deploy system polls it to know when the new version is ready

app.get('/health', async (req, res) => {
  // Quick liveness check — just proves the process is running
  res.json({ status: 'ok', version: process.env.APP_VERSION });
});

// Better: readiness check (proves app can actually serve traffic)
app.get('/ready', async (req, res) => {
  try {
    // Check database is reachable
    await db.query('SELECT 1');

    // Check Redis is reachable
    await redis.ping();

    res.json({
      status: 'ready',
      db: 'ok',
      redis: 'ok',
      uptime: process.uptime(),
      version: process.env.APP_VERSION,
    });
  } catch (error) {
    // Return 503 — load balancer will route away from this instance
    res.status(503).json({
      status: 'not ready',
      error: (error as Error).message,
    });
  }
});

